  ((( &( "mc" ) )) # UInt64  |-> mc_pre)
  **  ((( &( "nc" ) )) # UInt64  |-> nc_pre)
  **  ((( &( "input" ) )) # Ptr  |-> input_pre)
  **  ((( &( "weights" ) )) # Ptr  |-> weights_pre)
  **  ((( &( "widx_dmap" ) )) # Ptr  |-> widx_dmap_pre)
  **  ((( &( "nidx_nnzmap" ) )) # Ptr  |-> nidx_nnzmap_pre)
